import { ok, fail } from './result.js';
import { isValidDate, daysBetween } from './dates.js';
import { balanceDue } from './payments.js';
import { lineTotal, lineDiscount, lineVAT } from './invoices.js';

/**
 * Get overdue invoices as of a given date.
 * @param {Array} invoices
 * @param {string} asOf - Date in YYYY-MM-DD format
 * @returns {{ ok: true, value: Array } | { ok: false, error: string }}
 */
export function overdueInvoices(invoices, asOf) {
  if (!isValidDate(asOf)) {
    return fail('DATE_INVALID');
  }

  const overdue = invoices
    .filter(inv => (inv.status === 'issued' || inv.status === 'partially_paid') && inv.dueDate < asOf)
    .map(inv => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);

  return ok(overdue);
}

/**
 * Generate a VAT summary from invoices.
 * @param {Array} invoices
 * @returns {{ ok: true, value: Array<{ rate: number, base: number, vat: number }> }}
 */
export function vatSummary(invoices) {
  const vatMap = new Map();

  for (const invoice of invoices) {
    if (invoice.status !== 'issued' && invoice.status !== 'partially_paid' && invoice.status !== 'paid') {
      continue;
    }

    for (const line of invoice.lines) {
      const total = lineTotal(line);
      const discount = lineDiscount(line);
      const base = total - discount;
      const vat = lineVAT(line);
      const rate = line.vatRate;

      if (!vatMap.has(rate)) {
        vatMap.set(rate, { rate, base: 0, vat: 0 });
      }

      const entry = vatMap.get(rate);
      entry.base += base;
      entry.vat += vat;
    }
  }

  const summary = Array.from(vatMap.values()).sort((a, b) => b.rate - a.rate);

  return ok(summary);
}

