  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const invoice = issuedResult.value;
  const line = invoice.lines[0];

  const expectedBase = lineTotal(line) - lineDiscount(line);

  const result = vatSummary([invoice]);
  assert.equal(result.ok, true);
  const entry = result.value.find(e => e.rate === line.vatRate);
  assert(entry);
  assert.equal(entry.base, expectedBase);
